69	template <JoinKind KIND, JoinStrictness STRICTNESS, typename MapsTemplate>
70	JoinResultPtr HashJoinMethods<KIND, STRICTNESS, MapsTemplate>::joinBlockImpl(
71	    const HashJoin & join,
72	    ScatteredBlock block,
73	    const Block & block_with_columns_to_add,
74	    const MapsTemplateVector & maps_,
75	    bool is_join_get)
76	{
77	    constexpr JoinFeatures<KIND, STRICTNESS, MapsTemplate> join_features;
78	
79	    std::vector<JoinOnKeyColumns> join_on_keys;
80	    const auto & onexprs = join.table_join->getClauses();
81	    for (size_t i = 0; i < onexprs.size(); ++i)
82	    {
83	        const auto & key_names = !is_join_get ? onexprs[i].key_names_left : onexprs[i].key_names_right;
84	        join_on_keys.emplace_back(block, key_names, onexprs[i].condColumnNames().first, join.key_sizes[i]);
85	    }
86	
87	
88	    /** For LEFT/INNER JOIN, the saved blocks do not contain keys.
89	      * For FULL/RIGHT JOIN, the saved blocks contain keys;
90	      *  but they will not be used at this stage of joining (and will be in `AdderNonJoined`), and they need to be skipped.
91	      * For ASOF, the last column is used as the ASOF column
92	      */
93	    AddedColumns<!join_features.is_any_join> added_columns(
94	        block,
95	        block_with_columns_to_add,
96	        join.savedBlockSample(),
97	        join,
98	        std::move(join_on_keys),
99	        join.table_join->getMixedJoinExpression(),
100	        join.additional_filter_required_rhs_pos,
101	        join_features.is_asof_join,
102	        is_join_get);
103	
104	    bool has_required_right_keys = (join.required_right_keys.columns() != 0);
105	    added_columns.need_filter = join_features.need_filter || has_required_right_keys;
106	    added_columns.max_joined_block_rows = join.max_joined_block_rows;
107	    if (!added_columns.max_joined_block_rows)
108	        added_columns.max_joined_block_rows = std::numeric_limits<size_t>::max();
109	    else
110	        added_columns.reserve(join_features.need_replication);
111	
112	    size_t processed_rows = switchJoinRightColumns(maps_, added_columns, block.getSelector(), join.data->type, *join.used_flags, join.data->key_range);
113	    /// Do not hold memory for join_on_keys anymore
114	    added_columns.join_on_keys.clear();
115	
116	    std::optional<ScatteredBlock> next_scattered_block;
117	    if (0 < processed_rows && processed_rows < block.rows())
118	    {
119	        auto [raw_block, raw_selector] = std::move(block).detachData();
120	        auto split_selector = raw_selector.split(processed_rows);
121	        block = ScatteredBlock(raw_block, std::move(split_selector.first));
122	        next_scattered_block = ScatteredBlock(std::move(raw_block), std::move(split_selector.second));
123	    }
124	
125	    auto join_result = std::make_unique<HashJoinResult>(
126	        std::move(added_columns.lazy_output),
127	        std::move(added_columns.columns),
128	        std::move(added_columns.offsets_to_replicate),
129	        std::move(added_columns.filter),
130	        std::move(added_columns.matched_rows),
131	        std::move(block),
132	        HashJoinResult::Properties{
133	            *join.table_join,
134	            join.required_right_keys,
135	            join.required_right_keys_sources,
136	            join.max_joined_block_rows,
137	            join.max_joined_block_bytes,
138	            join.data->allocated_size / std::max<size_t>(1, join.data->rows_to_join),
139	            join_features.need_filter,
140	            is_join_get,
141	            join.joined_block_split_single_row,
142	            join.enable_lazy_columns_replication,
143	        });
144	
145	    if (next_scattered_block)
146	        join_result->setNextBlock(std::move(next_scattered_block.value()));
147	    return join_result;
148	}
